  "dock.aiGoogle": { en: "Google Gemini 2.5 Flash Mixing Intelligence", af: "Google Gemini 2.5 Flash Klankingenieurswese" },
  "landing.suiteTag": { en: "Creative Studio Suite", af: "Kreatiewe Ateljee-suite" },
  "landing.suiteTitle": { en: "Engineered for the Next Creative Era", af: "Ontwerp vir die Volgende Kreatiewe Era" },
  "landing.suiteSub": { en: "FutureBox connects world-class generative intelligence with dedicated workstation studios — built exclusively on Google DeepMind and Vertex AI models.", af: "FutureBox verbind wêreldklas generatiewe intelligensie met doelgerigte werkstasie-ateljees — eksklusief gebou op Google DeepMind- en Vertex KI-modelle." },
  "landing.roomPhoto": { en: "Post & Photo Studio", af: "Pos- en Foto-ateljee" },
  "landing.roomPhotoNote": { en: "Instant vector artwork templates, layered graphics canvas, rich typographic inspector, and multi-format release exports.", af: "Kits vektor-kunswerksjablone, laaggrafika-doek, ryk tipografie-inspekteur en veelformaat-vrystellingsuitvoere." },
  "landing.geminiReady": { en: "Google Gemini Vision", af: "Google Gemini Visie" },
  "landing.roomVideo": { en: "Cinema Video Desk", af: "Kinematiese Video-lessenaar" },
  "landing.roomVideoNote": { en: "9:16 reels and 16:9 widescreen scenes directed by Google Veo with cinematic camera movements, prompts, and auto-scroll prompters.", af: "9:16-video’s en 16:9-wyeskermtonele geregisseer deur Google Veo met kinematiese kamerabewegings en outo-rol-televolgers." },
  "landing.veoReady": { en: "Google Veo Generative Engine", af: "Google Veo Generatiewe Enjin" },
  "landing.roomBooth": { en: "ProBooth Multi-Track", af: "ProBooth Veelbaanateljee" },
  "landing.roomBoothNote": { en: "Full session lanes, Google Lyria AI neural chord progressions and instrument generation, plus Google Gemini Flash mixing engineer.", af: "Volledige sessiebane, Google Lyria KI neurale akkoordprogressies en instrumentgenerering, plus Google Gemini Flash-klankmenging." },
  "landing.lyriaReady": { en: "Google Lyria 48kHz Neural Audio", af: "Google Lyria 48kHz Neurale Klank" },
  "landing.roomInsights": { en: "Future Insights & Podcasts", af: "Toekomsinsigte en Potgooie" },
  "landing.roomInsightsNote": { en: "Visionary articles and podcasts with no ads, rated 96%–99% on source credibility across AI, vibecoding, tech, and business.", af: "100% advertensievrye visioenêre artikels en potgooie met 96%–99% bronbetroubaarheid oor KI, kodering, tegnologie en sake." },
  "landing.adFreeRating": { en: "No ads · 96%–99% credibility", af: "Geen advertensies · 96%–99% betroubaarheid" },
  "part.bars": { en: "bars", af: "mate" },
  "part.of": { en: "of", af: "van" },
  "part.at": { en: "at", af: "teen" },
  "part.make": { en: "Generate it", af: "Genereer dit" },
  "part.making": { en: "Generating\u2026", af: "Genereer tans\u2026" },
  "part.landed": { en: "It is a new lane, at the playhead.", af: "Dit is ’n nuwe baan, by die speelkop." },
  "part.failed": { en: "That part could not be generated. Nothing was charged.", af: "Daardie party kon nie gegenereer word nie. Niks is gehef nie." },
  "part.limit": { en: "The engine reads words, not the session. What comes back is described as being in this key and tempo — it is not locked to the click, so a part may need nudging into place. Drag it on its lane.", af: "Die enjin lees woorde, nie die sessie nie. Wat terugkom, word beskryf as in hierdie toonaard en tempo — dit is nie aan die klik vasgemaak nie, so ’n party mag dalk in plek geskuif moet word. Sleep dit op sy baan." },
  "staff.what": { en: "Five lines and the four spaces between them. Higher on the page is a higher note, and the sign at the front says which notes the song sharpens or flattens all the way through. Nothing here needs reading to use the app.", af: "Vyf lyne en die vier spasies tussen hulle. Hoër op die bladsy is ’n hoër noot, en die teken heel voor sê watter note die liedjie deurgaans verhoog of verlaag. Niks hiervan hoef gelees te kan word om die toepassing te gebruik nie." },
  "pro.barsAria": { en: "The session in bars", af: "Die sessie in mate" },
  "hooks.sharedGone": { en: "That song could not be fetched. The room hands out an address that expires, so opening this tab again usually fixes it.", af: "Daardie liedjie kon nie gehaal word nie. Die kamer gee ’n adres uit wat verval, so as jy hierdie oortjie weer oopmaak, werk dit gewoonlik." },
  "live.gone": { en: "That file is not there any more.", af: "Daardie l\u00eaer is nie meer daar nie." },
  /* Which nothing, on a video. The route knew and the screen did not print
     it, so five reports of "die videos wys nie" all looked the same. */
  "room.goneTitle": { en: "This one will not play", af: "Hierdie een sal nie speel nie" },
  "live.goneUnread": { en: "The video list could not be read just now. Try again in a moment.", af: "Die videolys kon nou nie gelees word nie. Probeer weer oor \u2019n oomblik." },
  "live.goneRow": { en: "This video is not in the account any more.", af: "Hierdie video is nie meer in die rekening nie." },
  "live.gonePath": { en: "This video is in the account, but no file was ever kept for it.", af: "Hierdie video is in die rekening, maar daar is nooit \u2019n l\u00eaer vir hom gestoor nie." },
  "live.goneFile": { en: "The file for this video is missing from the store.", af: "Die l\u00eaer vir hierdie video is weg uit die stoor." },
  "live.somewhere": { en: "somewhere", af: "\u00eerens" },
  "live.onNow": { en: "on now", af: "nou aan" },
  "live.in": { en: "in", af: "oor" },
  "live.min": { en: "min", af: "min" },
  "live.hours": { en: "hours", af: "uur" },
  "live.days": { en: "days", af: "dae" },
  /* ── The box is not a chat any more ──────────────────────────────────
     24 September 2026. It took five hundred characters of anything; it now
     takes a TikTok live address and nothing else. The old keys are gone
     rather than left pointing at a box that refuses what they invite. */
  "live.onlyLive": {
    en: "This is for TikTok live addresses only \u2014 where you are streaming right now. It is not a chat.",
    af: "Hierdie is net vir TikTok se lewendige adresse \u2014 waar jy nou stroom. Dit is nie \u2019n geselshoekie nie.",
  },
  "live.sayLive": { en: "https://www.tiktok.com/@you/live", af: "https://www.tiktok.com/@jy/live" },
