  "chan.noVideos": { en: "No videos yet. Make one at the Video desk and it appears here on its own — there is nothing to move.", af: "Nog geen video\u2019s nie. Maak een by die Video-lessenaar en dit verskyn vanself hier — daar is niks om te skuif nie." },
