  "edit.engineWhen": { en: "Those two are priced and on the plan cards, and are not switched on yet: sending video of a person to another company needs an answer about what that company may do with it first. Making a shot you do not have is switched on — it is the AI wand, on a shot’s menu and under Looks.", af: "Daardie twee is geprys en staan op die planskaarte, en is nog nie aangeskakel nie: om video van ’n persoon na ’n ander maatskappy te stuur, verg eers ’n antwoord oor wat daardie maatskappy daarmee mag doen. Om ’n skoot te maak wat jy nie het nie, is aangeskakel — dit is die KI-towerstaf, op ’n skoot se kieslys en onder Voorkoms." },
