  "pro.ampSignIn": { en: "Sign in to search the catalogue.", af: "Meld aan om die katalogus te deursoek." },
  "pro.ampFetching": { en: "Fetching it\u2026", af: "Haal dit\u2026" },
  "pro.ampOnShelf": { en: "It is on your shelf. Put it on a track.", af: "Dit is op jou rak. Sit dit op \u2019n baan." },
