  "radar.boostRequest": { en: "Boost request", af: "Versoek om ’n hupstoot" },
  "radar.boostUrl": { en: "Paste the link to your post once it is live", af: "Plak die skakel na jou plasing sodra dit lewendig is" },
  "radar.needsLink": { en: "Paste the link to your post first.", af: "Plak eers die skakel na jou plasing." },
  "radar.queueIt": { en: "Queue it", af: "Sit dit in die ry" },
  "radar.cancel": { en: "Cancel", af: "Kanselleer" },
  "radar.byHand": { en: "We look at boost requests by hand, so this is a request rather than an automatic repost.", af: "Ons kyk na hupstoot-versoeke met die hand, so dit is ’n versoek eerder as ’n outomatiese herplasing." },
  "home.signIn": { en: "Sign in", af: "Teken in" },
