  "edit.shotHintChange": { en: "Type here\u2026 e.g. make it night, add rain, turn the car red", af: "Tik hier\u2026 bv. maak dit nag, voeg re\u00ebn by, maak die motor rooi" },
  "edit.shotHintType": { en: "Type here\u2026 e.g. a konsertina on a stoep at sunset, the curtain moving in the wind", af: "Tik hier\u2026 bv. \u2019n konsertina op \u2019n stoep met sonsondergang, die gordyn wat in die wind beweeg" },
