  "veo.title": { en: "Animate this frame with AI", af: "Animeer hierdie raam met KI" },
  "veo.desc": { en: "Takes the frame you are on, lets the AI change it from your words, and makes it move with one of the studio’s video engines. That one frame and your words are sent; the price is on the button that makes it.", af: "Neem die raam waarop jy is, laat die KI dit volgens jou woorde verander, en laat dit beweeg met een van die ateljee se video-enjins. Daardie een raam en jou woorde word gestuur; die prys staan op die knoppie wat dit maak." },
