  "account.videos": { en: "Videos and clips", af: "Video’s en grepe" },
  "account.vaultNote": { en: "Counted on this device. The channel holds them.", af: "Op hierdie toestel getel. Die kanaal hou hulle." },
  "account.viewVault": { en: "View the vault →", af: "Kyk na die kluis →" },
  "theme.toDark": { en: "Switch to dark", af: "Skakel na donker" },
  "theme.toLight": { en: "Switch to light", af: "Skakel na lig" },
  "account.aMonth": { en: "a month", af: "per maand" },
  "account.seePlans": { en: "See the plans", af: "Sien die planne" },
  "account.changePlan": { en: "Change your plan", af: "Verander jou plan" },
  "account.credits": { en: "Credits", af: "Krediete" },
  "account.creditsUnreachable": { en: "Your balance could not be fetched just now. Nothing has been spent \u2014 try again in a moment.", af: "Jou saldo kon nou nie gehaal word nie. Niks is bestee nie \u2014 probeer weer oor \u2019n oomblik." },
  "account.creditsOff": { en: "This app has no accounts set up, so nothing is counted.", af: "Hierdie toep het geen rekeninge opgestel nie, so niks word getel nie." },
  "account.creditsMonthly": { en: "a month on this plan", af: "per maand op hierdie plan" },
  "account.creditsNote": { en: "What a generation costs is said on the button before you press it. Credits from your plan land each month; anything you buy on top does not expire.", af: "Wat elke maaksel kos, staan op die knoppie voordat jy dit druk. Krediete van jou plan kom elke maand; enigiets wat jy bykoop, verval nie." },
  "account.taste": { en: "What the app has noticed", af: "Wat die toep opgemerk het" },
  "account.tasteNone": { en: "Nothing yet. Make a few things and it will start suggesting the kind you actually make.", af: "Nog niks nie. Maak \u2019n paar goed en dit sal begin voorstel wat jy werklik maak." },
  "account.tasteGenre": { en: "what you make", af: "wat jy maak" },
  "account.tasteRoom": { en: "where you work", af: "waar jy werk" },
  "account.tasteNote": { en: "A count of each kind and when it last happened \u2014 not a record of when you work. It is what lets the welcome screen and the copilot suggest the kind of thing you actually make, on any device you sign in on.", af: "\u2019n Telling van elke soort en wanneer dit laas gebeur het \u2014 nie \u2019n rekord van wanneer jy werk nie. Dit is wat die verwelkomingsblad en die copilot laat voorstel wat jy werklik maak, op enige toestel waarop jy aanteken." },
  "account.tasteForget": { en: "Clear this and start again", af: "Vee dit uit en begin oor" },
  "account.help": { en: "A question, or a problem", af: "\u2019n Vraag, of \u2019n probleem" },
  "account.kids": { en: "The kids room", af: "Die kinderkamer" },
  "account.kidsNote": { en: "Set an allowance and a clock, then hand the phone over. Six doors in there, and the allowance holds wherever they go.", af: "Stel \u2019n toelaag en \u2019n klok, en gee dan die foon oor. Ses deure daarbinne, en die toelaag hou waar hulle ook al gaan." },
  "account.story": { en: "Story mode", af: "Storiemodus" },
  "account.storyNote": { en: "A story written and drawn a page at a time, read aloud, and kept on the shelf.", af: "\u2019n Storie wat een bladsy op \u2019n keer geskryf en geteken word, hardop voorgelees, en op die rak gehou." },
  "account.helpNote": { en: "Ask about the app, your plan or a charge and get an answer here \u2014 or write to a person.", af: "Vra oor die toep, jou plan of \u2019n heffing en kry hier \u2019n antwoord \u2014 of skryf aan \u2019n mens." },
  "account.channel": { en: "Your channel and your picture", af: "Jou kanaal en jou foto" },
  "account.channelNote": { en: "Your songs, your playlists, your profile picture.", af: "Jou liedjies, jou speellyste, jou profielfoto." },
  "account.legal": { en: "The", af: "Die" },
  "sub.none": { en: "You are not on a paid plan, so there is nothing to cancel. If you ever are, the button to end it is here, on this screen.", af: "Jy is nie op \u2019n betaalde plan nie, so daar is niks om te kanselleer nie. As jy ooit is, staan die knoppie om dit te be\u00ebindig hier, op hierdie blad." },
  "conn.title": { en: "Where else you are", af: "Waar jy nog is" },
  "conn.what": { en: "Your name on each platform. It is not a login and nothing is posted for you \u2014 what it does is make every link this app prints the right link, and put your name on every caption it writes. Kept on this device.", af: "Jou naam op elke platform. Dit is nie \u2019n intekening nie en niks word vir jou geplaas nie \u2014 wat dit doen is om elke skakel wat hierdie toep druk die regte skakel te maak, en jou naam op elke onderskrif te sit wat dit skryf. Op hierdie toestel gehou." },
  "conn.hint": { en: "handle, or paste your profile address", af: "@gebruikersnaam, of plak jou profiel se adres" },
  "radar.notSet": { en: "not set", af: "nie gestel nie" },
  "radar.handlesOnProfile": { en: "These are set on your profile, under \u201cWhere else you are\u201d.", af: "Hierdie word op jou profiel gestel, onder \u201cWaar jy nog is\u201d." },
  "account.terms": { en: "terms", af: "voorwaardes" },
  "account.and": { en: "and the", af: "en die" },
  "account.privacy": { en: "privacy notice", af: "privaatheidskennisgewing" },
  "auth.continueWith": { en: "Continue with", af: "Gaan voort met" },
  "auth.emailHint": { en: "you@example.com", af: "jy@voorbeeld.co.za" },
  "common.and": { en: "and", af: "en" },
  "auth.agreeAge": { en: "I am 18 or older, and I accept the", af: "Ek is 18 of ouer, en ek aanvaar die" },
  "auth.agreeTerms": { en: "terms", af: "voorwaardes" },
  "auth.agreePrivacy": { en: "privacy policy", af: "privaatheidsbeleid" },
  "auth.agreeTail": { en: ", including that music, voices and the copilot are generated by other companies and that what I send goes to them.", af: ", insluitend dat musiek, stemme en die copilot deur ander maatskappye gemaak word en dat wat ek stuur na hulle toe gaan." },
  "auth.mustAgree": { en: "Tick the box to say you are 18 or older and accept the terms.", af: "Merk die blokkie om te s\u00EA jy is 18 of ouer en aanvaar die voorwaardes." },
  "auth.signOut": { en: "Sign out", af: "Teken uit" },
  "auth.yourChannel": { en: "Your channel", af: "Jou kanaal" },
  "auth.working": { en: "One second\u2026", af: "Een sekonde\u2026" },
  "auth.checkEmail": { en: "Check your email \u2014 we sent a link to finish signing up.", af: "Kyk in jou e-pos \u2014 ons het ’n skakel gestuur om klaar te maak." },
  "auth.codeSent": { en: "We sent a six-digit code to", af: "Ons het \u2019n ses-syfer-kode gestuur na" },
