  "quiz.title": { en: "One thing about music", af: "Een ding oor musiek" },
  "quiz.sub": { en: "A new question every time you come back. Nothing is scored.", af: "\u2019n Nuwe vraag elke keer as jy terugkom. Niks word getel nie." },
  "quiz.tickFirst": { en: "Tick an answer first", af: "Merk eers \u2019n antwoord" },
