  "chan.getWords": { en: "Get the words", af: "Kry die woorde" },
  "chan.lyrics": { en: "Lyrics", af: "Lirieke" },
  "song.open": { en: "Open", af: "Maak oop" },
  "song.close": { en: "Close", af: "Maak toe" },
  "song.play": { en: "Play", af: "Speel" },
  "song.pause": { en: "Pause", af: "Wag" },
  "song.words": { en: "The words", af: "Die woorde" },
  "song.evenly": { en: "The words are spread evenly over the length \u2014 this one has not been listened to yet, so they can drift.", af: "Die woorde word gelykop oor die lengte versprei \u2014 daar is nog nie na hierdie een geluister nie, so hulle kan wegdryf." },
  "song.byEar": { en: "The words are laid on the singing this app measured in the song.", af: "Die woorde l\u00ea op die sang wat hierdie toep in die liedjie gemeet het." },
  "song.bySpan": { en: "The words are laid across the part of the file that is sung.", af: "Die woorde l\u00ea oor die deel van die l\u00eaer waarop gesing word." },
  /* The front page’s own drop-downs. Carli: everything folded except the
     one big class and the maker’s advert. */
  /* How a mix comes out of the Pro Booth. The surround line says what it
     is NOT on purpose: Dolby is licensed and trademarked, and this is the
     matrix fold those decoders unfold, which is arithmetic. */
  "mix.layout": { en: "How it comes out", af: "Hoe dit uitkom" },
  "mix.stereo": { en: "Stereo", af: "Stereo" },
  "mix.stereoNote": { en: "Two channels, exactly as the room plays it. This is the one to pick unless you have a reason not to.", af: "Twee kanale, presies soos die kamer dit speel. Kies hierdie een tensy jy \u2019n rede het om nie." },
  "mix.mono": { en: "Mono", af: "Mono" },
  "mix.monoNote": { en: "One channel. Radio, a phone speaker, a shop \u2014 and the honest test of a mix, because anything that disappears here was only there because of the width.", af: "Een kanaal. Radio, \u2019n foon se luidspreker, \u2019n winkel \u2014 en die eerlike toets van \u2019n mengsel, want enigiets wat hier verdwyn was net daar oor die wydte." },
  "mix.surround": { en: "Surround (matrix)", af: "Surround (matriks)" },
  "mix.surroundNote": { en: "Still two channels, folded so a surround receiver in its matrix mode can put the middle of the mix in the centre speaker and the sides behind you. It is not a Dolby file and we do not licence Dolby \u2014 on anything else it plays as ordinary stereo.", af: "Steeds twee kanale, gevou sodat \u2019n surround-ontvanger in sy matriks-modus die middel van die mengsel in die middelste luidspreker kan sit en die kante agter jou. Dit is nie \u2019n Dolby-l\u00eaer nie en ons lisensieer nie Dolby nie \u2014 op enigiets anders speel dit as gewone stereo." },
  "fold.pods": { en: "Podcasts worth the hour", af: "Podcasts wat die uur werd is" },
  "fold.classes": { en: "The rest of the classes", af: "Die res van die klasse" },
  "fold.creations": { en: "Music and video members made", af: "Musiek en video’s wat lede gemaak het" },
  "fold.radar": { en: "What changed this week", af: "Wat die week verander het" },
  "feed.creationsWaiting": { en: "This is where members\u2019 own music and videos go. Nothing invented sits here in the meantime \u2014 what is on the wall is what people have actually made.", af: "Hier kom lede se eie musiek en video\u2019s. Niks versinde sit intussen hier nie \u2014 wat op die muur is, is wat mense werklik gemaak het." },
  "feed.creationsGo": { en: "See what people are posting", af: "Kyk wat mense plaas" },
  "home.setNo": { en: "Set", af: "Stel" },
  "feed.from": { en: "From", af: "Van" },
  "home.otherPicks": { en: "Show me different ones", af: "Wys my ander" },
  "pro.amp": { en: "Amp", af: "Versterker" },
  "booth.withAi": { en: "The AI singer is on this backing \u2014 sing along with it.", af: "Die AI-sanger is op hierdie begeleiding \u2014 sing saam met hom." },
  "booth.withAiWhy": { en: "An unsplit song plays as it was made, voice and all, which is what makes it a guide. On headphones your take comes back with only your voice on it. Out loud, the microphone hears the AI singer too \u2014 split the song below to take that voice out of the backing.", af: "\u2019n Ongesplitste liedjie speel soos dit gemaak is, stem en al, en dit is juis wat dit \u2019n gids maak. Met oorfone kom jou opname terug met net jou stem op. Hardop hoor die mikrofoon die AI-sanger ook \u2014 skei die liedjie hieronder om daardie stem uit die begeleiding te haal." },
  "pro.ampBring": { en: "Bring in an amp", af: "Bring \u2019n versterker in" },
  /* TONE3000 is a company's name and stays itself in both languages, the
     same rule the other suppliers follow. The sentences around it do not. */
  "pro.t3kBrowse": { en: "Browse TONE3000", af: "Blaai deur TONE3000" },
  "pro.t3kNo": { en: "TONE3000 could not be reached just now.", af: "TONE3000 kon nie nou bereik word nie." },
  "pro.t3kAgain": { en: "Sign in to TONE3000 again to bring this amp in.", af: "Teken weer by TONE3000 in om hierdie versterker in te bring." },
  "pro.t3kGone": { en: "That amp could not be brought in.", af: "Daardie versterker kon nie ingebring word nie." },
  "pro.t3kNoNam": { en: "That one has no NAM capture in it \u2014 it may be in another format, like AIDA-X. Pick an amp whose files list a .nam.", af: "Daardie een het nie \u2019n NAM-vaslegging in nie \u2014 dit is dalk \u2019n ander formaat, soos AIDA-X. Kies \u2019n versterker waarvan die l\u00eaers \u2019n .nam wys." },
  "pro.t3kNoFile": { en: "TONE3000 has no file to download for that amp.", af: "TONE3000 het geen l\u00eaer om vir daardie versterker af te laai nie." },
  "pro.t3kStore": { en: "The file was found and would not download. Worth one more try.", af: "Die l\u00eaer is gevind en wou nie aflaai nie. Dit is een keer weer probeer werd." },
  "pro.t3kRefused": { en: "TONE3000 refused the download. Try another amp; if it keeps happening, sign in to TONE3000 again.", af: "TONE3000 het die aflaai geweier. Probeer \u2019n ander versterker; hou dit aan, teken weer by TONE3000 in." },
  "pro.t3kOurs": { en: "Something on our side could not be reached. Try again in a moment.", af: "Iets aan ons kant kon nie bereik word nie. Probeer oor \u2019n oomblik weer." },
  "pro.t3kNoLoad": { en: "That capture did not load as an amp here.", af: "Daardie vaslegging het nie hier as \u2019n versterker gelaai nie." },
  "pro.t3kGot": { en: "It is on your amp shelf. Put it on a track.", af: "Dit is op jou versterker-rak. Sit dit op \u2019n baan." },
  "pro.t3kNone": { en: "No amp was chosen.", af: "Geen versterker is gekies nie." },
  "pro.t3kClose": { en: "Close", af: "Maak toe" },
  "pro.amping": { en: "Running it through\u2026", af: "Stuur dit deur\u2026" },
  "pro.ampOff": { en: "Take it off", af: "Haal dit af" },
  "pro.ampFailed": { en: "That file did not load as an amp.", af: "Daardie l\u00eaer het nie as \u2019n versterker gelaai nie." },
  "pro.ampWhat": { en: "A .nam capture of a real amplifier \u2014 the file any Neural Amp Modeler plugin loads. It runs on this device and is baked into the lane, so the mixdown hears exactly what you do. Your recording is kept underneath.", af: "\u2019n .nam-vasvang van \u2019n regte versterker \u2014 die l\u00eaer wat enige Neural Amp Modeler-inprop laai. Dit loop op hierdie toestel en word in die baan ingebak, so die mengsel hoor presies wat jy hoor. Jou opname bly onder behoue." },
