  "pod.signIn": { en: "Sign in to make a show", af: "Teken in om \u2019n program te maak" },
  "pod.signInNote": { en: "A show belongs to an account \u2014 that is what the feed is addressed to.", af: "\u2019n Program behoort aan \u2019n rekening \u2014 dis waaraan die stroom geadresseer is." },
