  "art.notInPlay": { en: "Album art is not sold in the Android app.", af: "Albumkuns word nie in die Android-toep verkoop nie." },
  "sub.playManage": { en: "Change or stop it in Google Play", af: "Verander of stop dit in Google Play" },
  "sub.playWhere": { en: "You took this plan in the Android app, so Google Play holds the payment. Stopping it there ends it at the close of the month already paid.", af: "Jy het hierdie plan in die Android-toep geneem, so Google Play hou die betaling. As jy dit daar stop, eindig dit aan die einde van die maand wat reeds betaal is." },
  "kids.packsHowPlay": { en: "Kids credits are spent only in the kids room, before any allowance below. Paid through Google Play; a monthly pack renews until you stop it in Google Play.", af: "Kinderkrediete word net in die kinderkamer gebruik, voor enige toelae hieronder. Betaal deur Google Play; \u2019n maandelikse pak hernu totdat jy dit in Google Play stop." },
  "kids.playManage": { en: "Monthly packs in Google Play", af: "Maandelikse pakke in Google Play" },
  "stpl.previewBack": { en: "Back to the templates", af: "Terug na die sjablone" },
  "stpl.stillNote": { en: "A photo cannot move, so here it goes on as a still. To keep the motion, pick it in the Video Editor.", af: "\u2019n Foto kan nie beweeg nie, so hier gaan dit op as \u2019n stilbeeld. Kies dit in die video-redigeerder om die beweging te hou." },
  "stpl.previewUse": { en: "Use this template", af: "Gebruik hierdie sjabloon" },
  "motion.none": { en: "Still", af: "Stil" },
  "motion.noneWhat": { en: "The words are simply there.", af: "Die woorde is net daar." },
  "motion.pop": { en: "Pop", af: "Spring" },
  "motion.popWhat": { en: "Grow in from small, with a little bounce.", af: "Groei in van klein af, met \u2019n klein wip." },
  "motion.rise": { en: "Rise", af: "Styg" },
  "motion.riseWhat": { en: "Float up into place as they fade in.", af: "Dryf op na hul plek terwyl hulle verskyn." },
  "motion.slide": { en: "Slide", af: "Gly" },
  "motion.slideWhat": { en: "Come in from the left and settle.", af: "Kom van links af in en gaan l\u00ea." },
  "motion.type": { en: "Typewriter", af: "Tikmasjien" },
  "motion.typeWhat": { en: "Appear one letter at a time.", af: "Verskyn een letter op \u2019n slag." },
  "motion.fade": { en: "Fade", af: "Vervaag" },
  "motion.fadeWhat": { en: "Fade in slowly.", af: "Kom stadig te voorskyn." },
  "motion.drop": { en: "Drop", af: "Val" },
  "motion.dropWhat": { en: "Fall in from above and land.", af: "Val van bo af in en land." },
  "motion.pulse": { en: "Pulse", af: "Klop" },
  "motion.pulseWhat": { en: "Beat gently for as long as they are up.", af: "Klop saggies so lank as wat hulle op is." },
  "motion.flip": { en: "Flip up", af: "Flip op" },
  "motion.flipWhat": { en: "Turn up into place like a card.", af: "Draai op na sy plek soos ’n kaart." },
