  "motion.scaleWhat": { en: "Grow from small to full size.", af: "Groei van klein tot volle grootte." },
  "motion.shrink": { en: "Zoom down", af: "Krimp in" },
  "motion.shrinkWhat": { en: "Come down from very big and settle.", af: "Kom af van baie groot en gaan sit." },
  "motion.write": { en: "Random write on", af: "Lukrake letters" },
  "motion.writeWhat": { en: "Scrambled letters settle into the words.", af: "Deurmekaar letters val in plek tot die woorde." },
  "motion.rotate": { en: "Rotate in", af: "Draai in" },
  "motion.rotateWhat": { en: "Swing round into place.", af: "Swaai om na sy plek." },
  "motion.stretch": { en: "Stretch zoom", af: "Rek in" },
