  "motion.glitch": { en: "Glitch", af: "Steuring" },
  "motion.glitchWhat": { en: "Jump and flicker in like a bad signal.", af: "Spring en flikker in soos ’n swak sein." },
  "motion.flicker": { en: "Neon flicker", af: "Neonflikker" },
  "motion.flickerWhat": { en: "Flicker on like a neon sign, and now and then again.", af: "Flikker aan soos ’n neonbord, en so af en toe weer." },
