  "hosts.scriptLabel": { en: "Dialogue Script", af: "Dialoogteks" },
  "edit.wandSay": { en: "This frame is on the bench. Say what the AI must change, press Draw, then Make it move to put the new shot on the clock.", af: "Hierdie raam is op die bank. S\u00ea wat die KI moet verander, druk Teken, dan Laat dit beweeg om die nuwe skoot op die klok te sit." },
  /* The cutting room, 15 October 2026 — Carli: "Kyk mooi of elke funksie in
     ... video editor ... werk." Each of these is a sentence where a press
     used to do nothing, or said something untrue. */
  "edit.channelOut": { en: "Sign in to see your channel. Clips from this device can come in without signing in.", af: "Teken in om jou kanaal te sien. Knipsels van hierdie toestel kan sonder om in te teken inkom." },
  "edit.channelBroke": { en: "Your channel could not be reached just now. Check the connection and press Again.", af: "Jou kanaal kon nou nie bereik word nie. Kyk na die verbinding en druk Weer." },
  "edit.veoNoShot": { en: "Pick a shot on the clock first, then stand on the frame you want to animate.", af: "Kies eers ’n skoot op die klok, en staan dan op die raam wat jy wil animeer." },
  "edit.clipCutEdge": { en: "That is too close to the end of the shot to cut. Tap a little further in.", af: "Dit is te naby aan die punt van die skoot om te sny. Tik ’n bietjie verder in." },
  "edit.shapePost": { en: "Feed post 4:5", af: "Voerplasing 4:5" },
  "edit.sizeCustomNow": { en: "Your own size: {w} × {h}", af: "Jou eie grootte: {w} × {h}" },
  "edit.templateNoRecord": { en: "This browser cannot record the template as a clip. Chrome or Edge can. The shape and the name are set; bring a clip in to go with them.", af: "Hierdie blaaier kan nie die sjabloon as ’n knipsel opneem nie. Chrome of Edge kan. Die vorm en die naam is gestel; bring ’n knipsel in om daarby te pas." },
  "edit.templateFailed": { en: "That template could not be made into a clip just now. The shape and the name are set; try the template again, or bring a clip in.", af: "Daardie sjabloon kon nou nie in ’n knipsel omskep word nie. Die vorm en die naam is gestel; probeer die sjabloon weer, of bring ’n knipsel in." },
  "edit.wordsGlow": { en: "A glow round the letters", af: "’n Gloed om die letters" },
  "edit.needsShot": { en: "This works on the shot you have picked. Tap a shot on the clock — or bring a clip in first if the clock is empty.", af: "Dit werk op die skoot wat jy gekies het. Tik op ’n skoot op die klok — of bring eers ’n knipsel in as die klok leeg is." },
  "stpl.videoOnlySub": { en: "Templates that move. The one you pick becomes a clip on your clock, with its words on top to change.", af: "Sjablone wat beweeg. Die een wat jy kies, word ’n knipsel op jou klok, met sy woorde bo-op om te verander." },
  "edit.wandTitle": { en: "Change this frame with AI", af: "Verander hierdie raam met KI" },
  "edit.wandShut": { en: "Put the wand away", af: "Sit die towerstaf weg" },
  "edit.clipCut": { en: "Cut here", af: "Sny hier" },
  "edit.clipWand": { en: "AI wand", af: "KI-towerstaf" },
  "edit.markBrand": { en: "Your brand logo", af: "Jou handelsmerklogo" },
  "edit.markBrandGo": { en: "Put my brand logo on", af: "Sit my handelsmerklogo op" },
  "post.cutNothingToKeep": { en: "No person found, and no plain background round anything either \u2014 so nothing was taken out. Use Cut out a shape and draw round what you want to keep.", af: "Geen mens gevind nie, en ook geen gewone agtergrond om iets nie \u2014 so niks is uitgehaal nie. Gebruik Sny \u2019n vorm uit en trek om wat jy wil hou." },
  "post.cutDoneShort": { en: "Background removed. Save as PNG to keep it see-through.", af: "Agtergrond verwyder. Stoor as PNG om dit deursigtig te hou." },
  "post.magicTap": { en: "Tap the part of the photo first.", af: "Tik eers op die deel van die foto." },
  "post.magicSayWhat": { en: "Say what it should become first.", af: "S\u00ea eers wat dit moet word." },
  "post.stepMagic": { en: "a magic touch", af: "\u2019n towerraak" },
  "post.magicDone": { en: "Done. Only that part changed \u2014 press Put it back if you liked it better before.", af: "Klaar. Net daardie deel het verander \u2014 druk Sit dit terug as jy dit eerder soos voorheen wil h\u00ea." },
  "post.magicIntoThing": { en: "Change it into\u2026 a red sports car", af: "Verander dit in\u2026 \u2019n rooi sportmotor" },
  "post.magicInto": { en: "Change it into\u2026 a sunflower", af: "Verander dit in\u2026 \u2019n sonneblom" },
  "post.magicBetter": { en: "Make it better", af: "Maak dit beter" },
  "post.magicChange": { en: "Change it", af: "Verander dit" },
  "post.magicFill": { en: "Take it away", af: "Haal dit weg" },
  "post.magicPrice": { en: "{n} credits a press. Only this part is sent and only this part changes.", af: "{n} krediete per druk. Net hierdie deel word gestuur en net hierdie deel verander." },
  "post.cutWhatOne": { en: "One press: a person is cut out cleanly; a logo or drawing loses its plain background. On your phone, no credits.", af: "Een druk: \u2019n mens word skoon uitgesny; \u2019n logo of tekening verloor sy gewone agtergrond. Op jou foon, geen krediete nie." },
  "post.groundOnly": { en: "Only a plain background (logos, drawings)", af: "Net \u2019n gewone agtergrond (logo\u2019s, tekeninge)" },
  "post.magicNone": { en: "Bring a photo in first.", af: "Bring eers \u2019n foto in." },
  "post.magicReady": { en: "That part is marked. Choose what the AI does.", af: "Daardie deel is gemerk. Kies wat die KI doen." },
  "post.magicSize": { en: "How big a part", af: "Hoe groot \u2019n deel" },
  "post.shapesStart": { en: "Pick a shape. Then drag it on the photo, and pull its corner to size it.", af: "Kies \u2019n vorm. Sleep dit dan op die foto, en trek aan sy hoek om die grootte te stel." },
  "post.markSizeSlide": { en: "Size", af: "Grootte" },
