  "collab.loading": { en: "Looking\u2026", af: "Kyk\u2026" },
  "collab.oneAsked": { en: "Somebody wants to work with you", af: "Iemand wil met jou saamwerk" },
  "collab.manyAsked": { en: "people want to work with you", af: "mense wil met jou saamwerk" },
  "collab.accept": { en: "Accept", af: "Aanvaar" },
  "collab.decline": { en: "No thanks", af: "Nee dankie" },
  "collab.rooms": { en: "Working together", af: "Saamwerk" },
  "collab.roomsNote": {
    en: "A room opens when you both agree. Drop a song into it and the other person can hear what you mean \u2014 the song travels, not the file.",
    af: "\u2019n Kamer maak oop wanneer julle albei instem. Sit \u2019n liedjie daarin, dan hoor die ander een wat jy bedoel \u2014 die liedjie reis, nie die l\u00eaer nie.",
  },
  "collab.noRooms": {
    en: "None yet. Find somebody whose sound is near yours below, and ask.",
    af: "Nog nie een nie. Kry hieronder iemand wie se klank naby joune is, en vra.",
  },
  "collab.saySomething": {
    en: "Nothing here yet. Say hello, or drop a song in.",
    af: "Nog niks hier nie. S\u00ea hallo, of sit \u2019n liedjie in.",
  },
  "collab.deskTitle": { en: "Collab Radar", af: "Collab Radar" },
  "collab.deskSub": { en: "& live room", af: "& lewendige kamer" },
  "collab.modeRadar": { en: "Collab Radar", af: "Collab Radar" },
  "collab.modeRoom": { en: "Live session room", af: "Lewendige sessiekamer" },
  "collab.inviteByHandle": { en: "Invite somebody by handle", af: "Nooi iemand per handvatsel" },
  "collab.handlePlaceholder": { en: "beatmaker99", af: "beatmaker99" },
  "collab.inviteBecause": { en: "I found your handle on FutureBox and would like to make something together.", af: "Ek het jou handvatsel op FutureBox gekry en wil graag iets saam maak." },
  "collab.invite": { en: "Invite", af: "Nooi" },
  "collab.lobby": { en: "Active session lobby", af: "Aktiewe sessie-voorportaal" },
  "collab.enterRoom": { en: "Enter the room", af: "Gaan die kamer binne" },
  "collab.roomTitle": { en: "Live session room", af: "Lewendige sessiekamer" },
  "collab.roomSub": { en: "The thread you share, the songs handed across, and the paired rooms where you work one turn at a time.", af: "Die draad wat julle deel, die liedjies wat oorgegee word, en die gepaarde kamers waar julle een beurt op ’n slag werk." },
  "collab.backToRadar": { en: "Back to the radar", af: "Terug na die radar" },
  "collab.roomHonest": { en: "Turns, solo and mute live in the paired rooms above, where two people really work on one thing. There is no turn timer in this thread, and no live microphones yet.", af: "Beurte, solo en demp woon in die gepaarde kamers hierbo, waar twee mense regtig aan een ding werk. Daar is geen beurt-horlosie in hierdie draad nie, en nog geen lewendige mikrofone nie." },
  "radar.sweepTitle": { en: "360° sweep", af: "360°-sweep" },
  "radar.sweepSub": { en: "Everybody who put a name on the radar. Nearer the middle means their songs scored nearer yours; the outer ring is people with nothing scored yet. Press a blip.", af: "Almal wat ’n naam op die radar gesit het. Nader aan die middel beteken hul liedjies het nader aan joune gepunt; die buitering is mense sonder ’n telling nog. Druk op ’n kol." },
  "radar.sweepHonest": { en: "The sweep is a picture. The people on it are real, and come from one read of the radar when this opens.", af: "Die sweep is ’n prentjie. Die mense daarop is eg, en kom van een lees van die radar toe dit oopgemaak is." },
  "radar.allGenres": { en: "All genres", af: "Alle genres" },
  "collab.aSong": { en: "a song", af: "\u2019n liedjie" },
  "collab.sing": { en: "Sing on it in my booth", af: "Sing daarop in my ateljee" },
  "collab.them": { en: "them", af: "hulle" },
  "collab.noFile": { en: "That song could not be opened.", af: "Daardie liedjie kon nie oopgemaak word nie." },
  "invite.title": { en: "Invite somebody who is not here yet", af: "Nooi iemand wat nog nie hier is nie" },
  "invite.why": { en: "The room only exists once two people have agreed, so somebody who does not have an account cannot be reached from here. This link lands them on the app, survives them signing up, and turns into a request from you with your reason already on it.", af: "Die kamer bestaan eers wanneer twee mense ingestem het, so iemand sonder \u2019n rekening kan nie van hier af bereik word nie. Hierdie skakel laat hulle op die toep land, oorleef hulle registrasie, en word \u2019n versoek van jou af met jou rede reeds daarop." },
  "invite.reason": { en: "What it is about", af: "Waaroor dit gaan" },
  "invite.reasonPlaceholder": { en: "What it is about \u2014 one line", af: "Waaroor dit gaan \u2014 een re\u00ebl" },
  "invite.make": { en: "Make a link", af: "Maak \u2019n skakel" },
  "invite.again": { en: "Make another link", af: "Maak nog \u2019n skakel" },
  "invite.copyLink": { en: "Copy the link", af: "Kopieer die skakel" },
  "invite.copyMail": { en: "Copy an email with it in", af: "Kopieer \u2019n e-pos daarmee in" },
  "invite.lasts": { en: "It works for a month and for a handful of people, then it stops. Anybody who has the link can use it, so send it rather than post it.", af: "Dit werk vir \u2019n maand en vir \u2019n handjievol mense, dan hou dit op. Enigiemand wat die skakel het kan dit gebruik, so stuur dit eerder as om dit te plaas." },
  "invite.mailHi": { en: "Hi,", af: "Hallo," },
  "invite.mailWhy": { en: "I make music with AI and I think there is something worth doing together.", af: "Ek maak musiek met AI en ek dink daar is iets wat die moeite werd is om saam te doen." },
  "invite.mailLink": { en: "This link opens a room where we can talk and pass songs back and forth:", af: "Hierdie skakel maak \u2019n kamer oop waar ons kan gesels en liedjies heen en weer kan aangee:" },
  "invite.mailLasts": { en: "It works for", af: "Dit werk vir" },
  "invite.mailDays": { en: "days", af: "dae" },
  "invite.someone": { en: "Somebody", af: "Iemand" },
  "invite.asked": { en: "has asked to work with you \u2014 it is waiting in Collab Radar.", af: "het gevra om met jou saam te werk \u2014 dit wag in Collab Radar." },
  "invite.alreadyLine": { en: "You already have a room with", af: "Jy het reeds \u2019n kamer met" },
  "invite.mine": { en: "That is your own link.", af: "Dit is jou eie skakel." },
  "invite.expired": { en: "That link has expired.", af: "Daardie skakel het verval." },
  "invite.usedUp": { en: "That link has been used as often as it can be.", af: "Daardie skakel is so dikwels gebruik as wat dit kan." },
