  "gone.voices": {
    en: "Any cloned voice \u2014 removed from the voice service too, not just from here",
    af: "Enige gekloonde stem \u2014 ook van die stemdiens af verwyder, nie net hier nie",
  },
  "gone.sounds": { en: "Any trained sound of your own", af: "Enige eie klank wat jy geleer het" },
  "gone.credits": { en: "Your credits, whether they were given or bought", af: "Jou krediete, gegee of gekoop" },
  "gone.collab": { en: "Your collaborations and everything said in them", af: "Jou samewerkings en alles wat daarin ges\u00ea is" },
  "gone.profile": { en: "Your profile and your channel", af: "Jou profiel en jou kanaal" },
  "gone.sub": {
    en: "If you are on a plan it is cancelled first. If that cancellation fails, nothing is deleted \u2014 being charged for an account you no longer have is the one thing that cannot be put right by asking.",
    af: "Is jy op \u2019n plan, word dit eers gekanselleer. Misluk daai kansellasie, word niks uitgevee nie \u2014 om gehef te word vir \u2019n rekening wat jy nie meer het nie, is die een ding wat nie met \u2019n versoek reggemaak kan word nie.",
  },
  "gone.type": { en: "Type", af: "Tik" },
  "gone.toConfirm": { en: "to confirm", af: "om te bevestig" },
  "gone.confirm": { en: "Delete it all", af: "Vee alles uit" },
  "gone.going": { en: "Deleting\u2026", af: "Vee uit\u2026" },
  "gone.keep": { en: "Keep my account", af: "Hou my rekening" },
  "gone.unreachable": { en: "Could not reach the app. Nothing was deleted.", af: "Kon nie die toep bereik nie. Niks is uitgevee nie." },
  "gone.failed": { en: "That did not work, and nothing was deleted.", af: "Dit het nie gewerk nie, en niks is uitgevee nie." },
  "pay.subLive": { en: "A month at a time. Cancel from inside the app whenever you like.", af: "Een maand op \u2019n slag. Kanselleer binne-in die toep wanneer jy wil." },
  "credits.cannotAsk": { en: "Could not read your credits just now", af: "Kon nie nou jou krediete lees nie" },
  "credits.notSetUp": { en: "Credits are not switched on for this app yet", af: "Krediete is nog nie vir hierdie toep aangeskakel nie" },
  "credits.short": { en: "You are short by", af: "Jy kort" },
  "credits.youHave": { en: "credits", af: "krediete" },
  "credits.browsing": { en: "Nothing is short — this is the shelf.", af: "Niks kort nie \u2014 dit is die rak." },
  "credits.shortNote": { en: "That needed", af: "Dit het" },
  "credits.andYouHave": { en: "and you have", af: "nodig gehad, en jy het" },
  "credits.freeIsReal": { en: "A generated song runs on an engine that charges by the minute, which is why it is the one thing that is not free. Everything your own device can make — the booth, the sketches, the timeline, the sound trainer — has no limit and never costs anything.", af: "’n Gegenereerde liedjie loop op ’n enjin wat per minuut vra, en dít is hoekom dit die een ding is wat nie gratis is nie. Alles wat jou eie toestel self kan maak — die opnamekamer, die sketse, die tydlyn, die klankafrigter — het geen perk nie en kos nooit iets nie." },
  "credits.topUpNote": {
    en: "A pack never expires, and it is used before next month\u2019s allowance.",
    af: "\u2019n Pakket verval nooit, en dit word voor volgende maand se toelae gebruik.",
  },
  "credits.close": { en: "Close", af: "Maak toe" },
  "credits.balanceTitle": { en: "What you have left to spend", af: "Wat jy oor het om te spandeer" },
  "credits.needPlan": { en: "Extra credits are for members on a plan. A plan includes credits every month, and the engine they are spent on — the video desk, your own cloned voice, and posting to your channels.", af: "Ekstra krediete is vir lede op ’n plan. ’n Plan sluit elke maand krediete in, en die enjin waarop hulle bestee word — die videolessenaar, jou eie gekloonde stem, en plasing na jou kanale." },
  "credits.seePlans": { en: "See the plans", af: "Sien die planne" },
  "credits.subNote": {
    en: "A pack costs more per credit than any monthly plan \u2014 it is for the month you needed more than usual. If you need more every month, a plan is the cheaper way.",
    af: "\u2019n Pakket kos meer per krediet as enige maandplan \u2014 dit is vir die maand toe jy meer as gewoonlik nodig gehad het. Het jy elke maand meer nodig, is \u2019n plan die goedkoper pad.",
  },

  // What a press costs, and how long it takes, said before the press rather
  // than after it. A per-minute job cannot name its figure until it knows the
  // length of the file, so it says the rate first and fills the total in as
  // soon as the audio is measured. The wait note is here because a job that
  // runs on someone else's GPUs looks broken while it is working, and an
  // unwarned person presses again — and pays again.
  "cost.perMinute": { en: "credits a minute", af: "krediete ’n minuut" },
  "cost.about": { en: "about", af: "sowat" },
  "cost.forThis": { en: "for this one", af: "vir hierdie een" },
  "cost.wait": { en: "takes a few minutes", af: "vat ’n paar minute" },
  "cost.waitLong": { en: "takes several minutes", af: "vat ’n hele paar minute" },

  "spend.title": { en: "What the engine has cost you", af: "Wat die enjin jou gekos het" },
  "spend.sub": { en: "The last 30 days, counted from what was actually generated. Only you see this.", af: "Die laaste 30 dae, getel uit wat werklik gemaak is. Net jy sien dit." },
  "spend.previews": { en: "Previews", af: "Voorskoue" },
  "spend.songs": { en: "Full songs", af: "Volle liedjies" },
  "spend.minutes": { en: "Minutes of audio", af: "Minute klank" },
  "spend.busiest": { en: "Busiest day", af: "Besigste dag" },
  "spend.bill": { en: "What you pay the engine a month, in rand", af: "Wat jy die enjin per maand betaal, in rand" },
  "spend.rate": { en: "Rand per dollar, for the comparison", af: "Rand per dollar, vir die vergelyking" },
  "spend.needBill": { en: "Put in what you actually pay and this works out your real cost a song \u2014 which is the number the comparison below should be judged against.", af: "Sit in wat jy werklik betaal, dan werk dit jou regte koste per liedjie uit \u2014 en dis die getal waarteen die vergelyking hieronder beoordeel moet word." },
  "spend.yours": { en: "Your real cost", af: "Jou werklike koste" },
  "spend.perSong": { en: "a full song", af: "per volle liedjie" },
  "spend.perPreview": { en: "a preview", af: "per voorskou" },
  "spend.derived": { en: "Worked out from your bill divided by the minutes actually generated. It falls as you make more, which is why a quiet month looks expensive.", af: "Uitgewerk uit jou rekening gedeel deur die minute wat werklik gemaak is. Dit val soos jy meer maak, en dis hoekom \u2019n stil maand duur lyk." },
  "spend.others": { en: "What the others charge, per full song", af: "Wat die ander vra, per volle liedjie" },
  "spend.licence": { en: "Licence", af: "Lisensie" },
  "spend.prev": { en: "preview", af: "voorskou" },
  "spend.published": { en: "Published rates read off the web in August 2026 \u2014 not quotes, and not verified against these providers\u2019 own APIs. Check the licence before moving anything you sell.", af: "Gepubliseerde tariewe van die web af in Augustus 2026 \u2014 nie kwotasies nie, en nie teen hierdie verskaffers se eie API\u2019s bevestig nie. Gaan die lisensie na voor jy iets skuif wat jy verkoop." },
  "counters.live": { en: "On FutureBox so far", af: "Op FutureBox tot dusver" },
