  "marklab.title": { en: "The Cubed mark, drawn by Google", af: "Die Cubed-merk, deur Google geteken" },
  "marklab.blurb": { en: "Four ways of drawing the same brief. Nothing we have drawn is sent \u2014 Google is given the brief in words and nothing else.", af: "Vier maniere om dieselfde opdrag te teken. Niks wat ons geteken het, word gestuur nie \u2014 Google kry die opdrag in woorde en niks anders nie." },
