  "post.ground": { en: "Plain background", af: "Egalige agtergrond" },
  "post.groundGo": { en: "Take a plain background off", af: "Haal ’n egalige agtergrond af" },
  "post.groundAll": { en: "A logo or drawing", af: "’n Logo of tekening" },
  "post.groundEdge": { en: "Around the outside only", af: "Net om die buitekant" },
  "post.groundWhat": { en: "For a logo, a drawing, or anything photographed on a plain sheet — including the grey-and-white squares a picture comes back with when it was asked for a see-through background. It works out what the background is from the edges of the frame. Included in your plan, and it happens on your own phone, so it uses no credits.", af: "Vir ’n logo, ’n tekening, of enigiets wat op ’n egalige vel afgeneem is — ook die grys-en-wit blokkies waarmee ’n prent terugkom wanneer daar vir ’n deursigtige agtergrond gevra is. Dit werk uit wat die agtergrond is uit die rande van die raam. Ingesluit in jou plan, en dit gebeur op jou eie foon, so dit gebruik geen krediete nie." },
  "post.groundDone": { en: "Background gone, and there is nothing behind it now — the squares are how the picture shows you that. Save it as PNG to keep it see-through; JPG cannot.", af: "Agtergrond weg, en daar is nou niks agter nie — die blokkies is hoe die prent dit vir jou wys. Stoor dit as PNG om dit deursigtig te hou; JPG kan nie." },
  "post.groundMost": { en: "That took nearly the whole picture away, which is right for a small mark on a big empty sheet and wrong if the subject has gone with it. Look at it, and press Put it back if it has.", af: "Dit het byna die hele prent weggevat, wat reg is vir ’n klein merk op ’n groot leë vel en verkeerd as die onderwerp saamgegaan het. Kyk daarna, en druk Sit dit terug as dit wel so is." },
  "post.groundNone": { en: "There is no plain background in this picture to take away. This one looks at the edges of the frame and removes what it finds there — it works on a logo, a drawing, or something photographed on a plain sheet. For a person, use Remove the background above.", af: "Daar is nie ’n egalige agtergrond in hierdie prent om weg te vat nie. Hierdie een kyk na die rande van die raam en haal weg wat dit daar kry — dit werk op ’n logo, ’n tekening, of iets wat op ’n egalige vel afgeneem is. Vir ’n mens, gebruik Verwyder die agtergrond hierbo." },
  "post.groundFailed": { en: "That background could not be taken out.", af: "Daardie agtergrond kon nie uitgehaal word nie." },
  "post.stepGround": { en: "taking a plain background out", af: "om ’n egalige agtergrond uit te haal" },
