  /* The advert report: what the money did, out of the platform's export. */
  "report.title": { en: "What the money did", af: "Wat die geld gedoen het" },
  "report.what": { en: "Export the report from your Ads Manager and drop the file here. It reads the columns whatever they are called, works out cost per click and cost per result, and puts each campaign next to the run that sent it out.", af: "Voer die verslag uit jou Ads Manager uit en los die l\u00eaer hier. Dit lees die kolomme hoe hulle ook al genoem word, werk koste per klik en koste per uitslag uit, en sit elke kampanje langs die lopie wat dit uitgestuur het." },
  "report.whyFile": { en: "A file rather than a connection, because reading numbers straight out of Meta or Google needs their app review and a verified company. You can already export them today, and the numbers are worth having today.", af: "’n L\u00eaer eerder as ’n verbinding, want om syfers reguit uit Meta of Google te lees verg hulle toep-hersiening en ’n geverifieerde maatskappy. Jy kan hulle vandag reeds uitvoer, en die syfers is vandag die moeite werd." },
  "report.pick": { en: "Take a report file", af: "Vat ’n verslagl\u00eaer" },
  "report.clear": { en: "Clear it", af: "Maak dit skoon" },
  "report.paste": { en: "Or paste it", af: "Of plak dit" },
  "report.pasteHint": { en: "Paste the rows straight out of the spreadsheet.", af: "Plak die rye reguit uit die sigblad." },
  "report.noSpend": { en: "No spend column was found in that file. Export again with the amount spent included \u2014 a report without the money in it is not the thing anybody is buying.", af: "Geen bestedingskolom is in daardie l\u00eaer gevind nie. Voer weer uit met die bedrag bestee ingesluit \u2014 ’n verslag sonder die geld daarin is nie waarvoor iemand betaal nie." },
  "report.bought": { en: "bought", af: "het gekoop" },
  "report.impressions": { en: "impressions", af: "vertonings" },
  "report.clicks": { en: "clicks", af: "klikke" },
  "report.and": { en: "and", af: "en" },
  "report.results": { en: "results", af: "uitslae" },
  "report.each": { en: "each", af: "elk" },
  "report.campaign": { en: "Campaign", af: "Kampanje" },
  "report.spent": { en: "Spent", af: "Bestee" },
  "report.seen": { en: "Seen", af: "Gesien" },
  "report.clicked": { en: "Clicked", af: "Geklik" },
  "report.ctr": { en: "Rate", af: "Koers" },
  "report.cpc": { en: "Per click", af: "Per klik" },
  "report.cpr": { en: "Per result", af: "Per uitslag" },
