  "report.unnamed": { en: "Unnamed", af: "Naamloos" },
  "report.row": { en: "result", af: "uitslag" },
  "report.matched": { en: "of these match a run you planned here.", af: "hiervan pas by ’n lopie wat jy hier beplan het." },
  "report.ignored": { en: "Columns it did not need:", af: "Kolomme wat dit nie nodig gehad het nie:" },
  "report.imported": { en: "Imported", af: "Ingevoer" },
