  "edit.zoomSlide": { en: "How close the picture is", af: "Hoe naby die prent is" },
  "make.mineToo": { en: "Then sing it in my own voice", af: "Sing dit dan in my eie stem" },
  "make.mineTooWhy": { en: "Your trained singing voice takes over the vocals once the song is made. Priced before it starts.", af: "Jou opgeleide sangstem neem die sang oor sodra die liedjie gemaak is. Die prys word gewys voor dit begin." },
  "canvas.simpleEmpty": { en: "Nothing written yet. Tell the copilot what to film, and it lands here.", af: "Nog niks geskryf nie. Sê vir die copilot wat om te verfilm, en dit land hier." },
  "kids.steps": { en: "The steps are whole songs, so nothing is left over that buys nothing.", af: "Die stappe is heel liedjies, sodat niks oorbly wat niks koop nie." },
  "kids.stories": { en: "Stories", af: "Stories" },
  "kids.bannerAlt": { en: "The FutureBox kids room: a safe studio where a child can be creative", af: "Die FutureBox kinderkamer: \u2019n veilige ateljee waar \u2019n kind kreatief kan wees" },
  "kids.grownUps": { en: "For the grown-up", af: "Vir die grootmens" },
  "kids.safeLine": { en: "No chat and no strangers. The room closes on your clock and stops at your number.", af: "Geen gesels en geen vreemdelinge nie. Die kamer sluit op jou klok en stop by jou getal." },
  "kids.doorsTitle": { en: "Six doors, all inside", af: "Ses deure, alles binne" },
  "kids.doorsWhy": { en: "Everything a child presses in there is on this page. Most of it has no price; the priced things below come out of the allowance you set.", af: "Alles wat \u2019n kind daarbinne druk, staan op hierdie bladsy. Die meeste daarvan het geen prys nie; die geprysde goed hieronder kom uit die toelaag wat jy stel." },
