  "post.benchStartsWhat": { en: "Finished designs to start from: the neon, synthwave, hologram and gold packs, and the starter pack of posters, flyers and covers.", af: "Klaar ontwerpe om mee te begin: die neon-, synthwave-, hologram- en goudpakke, en die beginpak van plakkate, strooibiljette en omslae." },
