  "pro.stemsAwayWhat": { en: "Each lane is written as a WAV of its own, named after the lane, cut where you cut it. Clean a lane with AI first if the room or the reverb is in the way.", af: "Elke baan word as sy eie WAV geskryf, na die baan genoem, gesny waar jy dit gesny het. Maak \u2019n baan eers met KI skoon as die kamer of die galm in die pad is." },
