  "story.deviceFull": { en: "There is no room left on this device. Make space and try again — or make the film now, before this is lost.", af: "Daar is geen plek oor op hierdie toestel nie. Maak plek en probeer weer — of maak die film nou, voordat dit verlore gaan." },
