  "story.what": { en: "Write or paste a story. It becomes pages, each with its own picture, read aloud in the voice you choose — then a film you can keep.", af: "Skryf of plak ’n storie. Dit word bladsye, elkeen met sy eie prent, voorgelees in die stem wat jy kies — en dan ’n film wat jy kan hou." },
