  "post.squeezeSmallNote": { en: "Squeezed harder: a much smaller file that loads fast, a little soft in fine detail. Same size in pixels.", af: "Harder saamgepers: ’n baie kleiner lêer wat vinnig laai, effens sag in fyn detail. Dieselfde grootte in piksels." },
  "post.squeezeStandardNote": { en: "The balance the platforms expect: sharp, at a sensible file size.", af: "Die balans wat die platforms verwag: skerp, teen ’n sinvolle lêergrootte." },
  "post.squeezeBestNote": { en: "Hardly squeezed at all: the sharpest file, and a bigger one. Same size in pixels.", af: "Amper glad nie saamgepers nie: die skerpste lêer, en ’n groter een. Dieselfde grootte in piksels." },
  "post.tooBigOut": { en: "At {w}×{h} that is too big for a phone to draw as one picture. Choose 1× under How big, or a smaller canvas size. Nothing was charged.", af: "Teen {w}×{h} is dit te groot vir ’n foon om as een prent te teken. Kies 1× onder Hoe groot, of ’n kleiner doekgrootte. Niks is gehef nie." },
  "post.stepDropShape": { en: "taking a shape away", af: "’n vorm weggooi" },
  "post.stepDropWords": { en: "taking words away", af: "woorde weggooi" },
  "post.stepTemplate": { en: "putting a template on", af: "’n sjabloon opsit" },
  "post.stepEdge": { en: "changing the cut edge", af: "die snyrand verander" },
  "stpl.failed": { en: "That template could not be opened. Nothing was changed — try another one.", af: "Daardie sjabloon kon nie oopgemaak word nie. Niks is verander nie — probeer ’n ander een." },
  "post.thingsTooBig": { en: "That picture is too big to send. Crop it or bring in a smaller one. Nothing was charged.", af: "Daardie prent is te groot om te stuur. Sny dit kleiner of bring ’n kleiner een in. Niks is gehef nie." },
  "post.liveNoClip": { en: "The engine finished but sent no clip back. Try it once more in a little while.", af: "Die enjin is klaar maar het geen video teruggestuur nie. Probeer dit oor ’n rukkie weer." },
  "post.copied": { en: "Copied.", af: "Gekopieer." },
  "post.copyFailed": { en: "That could not be copied. Hold your finger on the words above and copy them from there.", af: "Dit kon nie gekopieer word nie. Hou jou vinger op die woorde hierbo en kopieer hulle van daar af." },

