  "kidsbanner.alt": { en: "FutureBox Kids Dream Studio", af: "FutureBox Kinder Droomateljee" },
  "kidsbanner.title": { en: "A safe room where your child can be creative", af: "\u2019n Veilige plek waar jou kind kreatief kan wees" },
  "kidsbanner.sub": { en: "Real songs, videos, stories, drawings and games, in a room built for small hands \u2014 and for the grown-up who hands the phone over.", af: "Regte liedjies, video\u2019s, stories, tekeninge en speletjies, in \u2019n kamer gebou vir klein handjies \u2014 en vir die grootmens wat die foon oorhandig." },
  "kidsbanner.clock": { en: "You set the allowance and the clock. When the time is up, the room closes itself.", af: "Jy stel die toelaag en die horlosie. Wanneer die tyd om is, maak die kamer homself toe." },
  "kidsbanner.door": { en: "One room with no way out of it: no shop, no chat, no strangers, nothing shared.", af: "Een kamer sonder \u2019n uitgang: geen winkel, geen klets, geen vreemdelinge, niks wat gedeel word nie." },
  "kidsbanner.list": { en: "Every choice is a button from a list we wrote. One line can be typed, for a song, and it goes through the same safety gate every grown-up\u2019s words do.", af: "Elke keuse is \u2019n knoppie uit \u2019n lys wat ons geskryf het. Een re\u00ebl kan getik word, vir \u2019n liedjie, en dit gaan deur dieselfde veiligheidshek as elke grootmens se woorde." },
  "kidsbanner.wallet": { en: "Songs, videos and pictures cost credits off your account, never past the allowance. Playing them again uses no credits.", af: "Liedjies, video\u2019s en prente kos krediete van jou rekening af, nooit verby die toelaag nie. Om dit weer te speel gebruik geen krediete nie." },
  "kidsbanner.setUp": { en: "Set up the kids room", af: "Stel die kinderkamer op" },
  "kidsbanner.plans": { en: "See what it costs", af: "Kyk wat dit kos" },
  "kidsbanner.how": { en: "A grown-up signs in once and sets the allowance and the time. After that the child presses, and that is all.", af: "\u2019n Grootmens teken een keer in en stel die toelaag en die tyd. Daarna druk die kind, en dis al." },
