const STORAGE_KEY = 'futurebox.lang.v1';

/**
 * The choice, kept where a server months from now can read it.
 *
 * ── Why this is here at all ──────────────────────────────────────────────
 *
 * A receipt for a renewal is sent with nobody present: no browser, no request
 * from the member, months after they last opened the app. The webhook knows
 * one thing about them — the uuid Paystack carries — so a language chosen in
 * this file and stored in this browser was unreachable, and every renewal
 * receipt went out in English regardless of who it was for.
 *
 * It goes on the auth user's metadata rather than a table: there is no
 * per-account settings table in this app, and `lib/server/email.ts` was
 * already fetching that user to find the address, so the language comes back
 * in the same call rather than a second round trip inside a payment webhook.
 *
 * ── Why the import is dynamic ────────────────────────────────────────────
 *
 * `cloud.ts` pulls in the Supabase client. A language switcher is on the
 * landing page, so a static import would put that whole library in front of
 * anybody who has never signed in. Loaded when somebody actually switches,
 * which is once.
 *
 * ── Why nothing waits for it ─────────────────────────────────────────────
 *
 * Nothing on screen depends on it and the page has already changed language.
 * A failure — offline, signed out, Supabase not configured — costs a receipt
 * its language and must never cost somebody the language change they asked
 * for.
 */
async function keepOnAccount(next: Lang): Promise<void> {
  try {
    const cloud = await import('./cloud');
    if (!cloud.configured()) return;
    await cloud.rememberLanguage(next);
  } catch {
    // The browser's own copy is still correct, which is what this page reads.
  }
}

interface LangContext {
  lang: Lang;
  setLang: (next: Lang) => void;
  t: (key: string, fallback?: string) => string;
  /**
   * The language this page was showing when the account changed it, or null.
   *
   * Set only when signing in swapped the language *under somebody who was
   * already reading* — never on a first load, and never when they chose in
   * this browser, because then nothing was swapped. `LanguageSwitched` turns
   * it into a sentence and a way back.
   */
  switched: Lang | null;
  /** Keep the language that was on screen before the account changed it. */
  undoSwitch: () => void;
  /**
   * Where the language came from, for a person holding the phone it is wrong
   * on.
   *
   * This has been reported five times, fixed three times, and each fix was a
   * different guess about which of four things fails on her device. The
   * guessing is the problem: nothing in the app can be looked at from her side,
   * so every round is a theory built on a sentence.
   *
   * `/taal` prints this. It is not diagnostics for their own sake — it turns
   * "the language is still wrong" into a screenshot that names which input
   * was there, which was empty, and which one won.
   */
  sources: LangSources;
}

/** What each of the four places had to say on this load, and what won. */
export interface LangSources {
  /** Carried back from a sign-in in the address. Null when there was none. */
  readonly address: Lang | null;
  /** localStorage: a language, `null` when empty, `'blocked'` when it threw. */
  readonly storage: Lang | 'blocked' | null;
  readonly cookie: Lang | null;
  /** What the browser says the device is set to. A guess, never a choice. */
  readonly locale: string;
  /** The account, once asked. `'unasked'` until it has been. */
  readonly account: Lang | 'unasked' | 'none' | 'failed';
  /** Which of them decided what is on screen. */
  readonly won: 'address' | 'storage' | 'cookie' | 'account' | 'locale';
  /** Running as an installed app rather than in a browser tab. */
  readonly installed: boolean;
  /**
   * Who wrote the stored choice, and when — null where nothing is stored, or
   * where it was written before this was recorded.
   *
   * The row that ends the guessing. `en` in storage and `en` in the cookie
   * are only ever written together by a press, and there was no way to tell
   * which press. Now the page says so.
   */
  readonly writer: { why: LangWriter; at: number } | null;
}

const NOTHING_YET: LangSources = {
  address: null,
  storage: null,
  cookie: null,
  locale: '',
  account: 'unasked',
  won: 'locale',
  installed: false,
  writer: null,
};

const Context = createContext<LangContext>({
  lang: 'en',
  setLang: () => {},
  sources: NOTHING_YET,
  t: (key, fallback) => fallback ?? STRINGS[key]?.en ?? key,
  switched: null,
  undoSwitch: () => {},
});

/**
 * The same choice, in a cookie as well as in storage.
 *
 * ── Why two places for one small string ──────────────────────────────────
 *
 * Carli, for the third time and then in plain words: "By die inteken blad kan
 * jy jou taal kies. As ek afrikaans kies, dan moet dit afrikaans in log."
 *
 * She is right, that is rule 1, and it should already work — she presses the
 * picker, `setLang` stores Afrikaans, and signing in confirms it. It does work
 * on her laptop. What is different on a phone is that signing in **reloads the
 * page**, and two of the three places the choice lives do not survive that:
 *
 *   · `chose.current` is a ref inside a React component. A new document is a
 *     new component tree, and the ref is gone.
 *   · `localStorage` survives a reload — unless the browser is refusing to
 *     keep it, which is ordinary on a phone: Safari private browsing, an
 *     in-app webview, ITP clearing site data after a week away.
 *
 * With both gone, the app opens the new document with nothing stored, asks the
 * account, and applies the English it finds. She watches Afrikaans become
 * English and calls it a jump, which is exactly what it is.
 *
 * A cookie is the third place, and it is the one that covers the gap: it
 * survives a navigation like storage does, and it is written by a different
 * mechanism, so a browser refusing one is not refusing the other. It also
 * reaches the server, which is what would let `<html lang>` be right on the
 * first byte rather than corrected by an effect — worth having and not what
 * this is for.
 *
 * A year, because a language choice does not go stale. `SameSite=Lax` so it
 * rides an ordinary navigation and not a cross-site one; no `Secure` flag, so
 * it works on localhost for the probes as well as over https in production.
 */
const COOKIE = 'futurebox.lang';

function inCookie(): Lang | null {
  try {
    const found = document.cookie
      .split('; ')
      .find((one) => one.startsWith(`${COOKIE}=`));
    return asLang(found ? decodeURIComponent(found.slice(COOKIE.length + 1)) : null);
  } catch {
    return null;
  }
}

/**
 * Who wrote the language down, and when.
 *
 * ── Why a second key ─────────────────────────────────────────────────────
 *
 * Carli, six reports in: `/taal` showed `en` in storage and `en` in the
 * cookie on a phone where she had never knowingly chosen English. Both of
 * those are only ever written together by a *press* — `setLang` or
 * `undoSwitch` — so something had been pressed, and there was no way to find
 * out what. Another round of theories about somebody else's device.
 *
 * A value that cannot say where it came from is how six reports become seven.
 * This records the writer beside the value, and `/taal` prints it.
 *
 * Kept apart from the value rather than wrapped around it: the stored
 * language is a bare `'en'` or `'af'` and several places read it directly.
 * Changing its shape to carry a reason would be a migration, and a migration
 * on the one value this app has already got wrong six times is not a trade
 * worth making. A key that is missing simply means "written before this
 * existed", which is a true and useful answer.
 */
const WHY_KEY = 'futurebox.lang.why.v1';

export type LangWriter = 'pressed' | 'kept' | 'signin' | 'account';

function noteWriter(why: LangWriter): void {
  try {
    window.localStorage.setItem(WHY_KEY, JSON.stringify({ why, at: Date.now() }));
  } catch {
    /* Storage refused. The value it would have explained was refused too, so
       there is nothing left unexplained. */
  }
}

function whoWrote(): { why: LangWriter; at: number } | null {
  try {
    const said = JSON.parse(window.localStorage.getItem(WHY_KEY) ?? 'null') as unknown;
    if (!said || typeof said !== 'object') return null;
    const one = said as { why?: unknown; at?: unknown };
    const why = one.why;
    if (why !== 'pressed' && why !== 'kept' && why !== 'signin' && why !== 'account') return null;
    return { why, at: typeof one.at === 'number' ? one.at : 0 };
  } catch {
    return null;
  }
}

/**
 * Everything this device remembers about the language, forgotten.
 *
 * `/taal` offers it, and it is the only way out of a context that has the
 * wrong answer written into it. Pressing a language on that page is a choice
 * and choices are permanent by design — which is right, and left somebody who
 * pressed one by accident with no way back except clearing the whole site.
 */
export function forgetLanguage(): void {
  try {
    window.localStorage.removeItem(STORAGE_KEY);
    window.localStorage.removeItem(WHY_KEY);
  } catch {
    // Nothing was stored to remove.
  }
  try {
    document.cookie = `${COOKIE}=; path=/; max-age=0; SameSite=Lax`;
  } catch {
    // Same.
  }
}

function bakeCookie(next: Lang): void {
  try {
    document.cookie = `${COOKIE}=${next}; path=/; max-age=${365 * 24 * 60 * 60}; SameSite=Lax`;
  } catch {
    // Then storage and the ref are what there is, which is where this started.
  }
}

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  /* What was on screen when the account overruled it. See `switched`. */
  const [switched, setSwitched] = useState<Lang | null>(null);
  const [lang, setLangState] = useState<Lang>('en');

  /**
   * What this device thinks, worked out again rather than remembered.
   *
   * ── The ref that was here, and why it was wrong ──────────────────────
   *
   * This was a ref holding the language on screen, updated by an effect on
   * `lang`, so that the sign-in listener — registered once at mount — would
   * not compare against the mount-time value. That fixed the closure and left
   * a race underneath it.
   *
   * Supabase's listener fires immediately on registration with the session it
   * already has. On any load where somebody is already signed in, that happens
   * inside the *first* effect pass: `onArrival` has queued `setLangState('af')`
   * but React has not committed it, so the effect that copies `lang` into the
   * ref has not run, and the ref still says English — the initial state.
   *
   * The comparison that decides whether to announce the switch is
   * `said === showing`. With a stale `showing` of English and an account that
   * says English, they match, so nothing is announced — and then the Afrikaans
   * that `onArrival` had queued is replaced by English with no word about it.
   *
   * Which is exactly what Carli saw, in the opposite direction to last time:
   * "Wanneer ek vanuit die afrikaanse skerm in log, spring hy na die engels toe
   * wanneer mens in is." The switch is the rule working. The silence was a
   * race.
   *
   * So the decision no longer asks what has been painted. It works out what
   * this device would show, from the same two inputs `onArrival` uses, at the
   * moment it decides. Nothing to be stale, and no ordering to get right.
   */
  const deviceWould = (stored: string | null): Lang => {
    try {
      return onArrival(stored, navigator.language).lang;
    } catch {
      return 'en';
    }
  };

  /**
   * The choice made in this session, when storage could not keep it.
   *
   * ── Carli's phone ────────────────────────────────────────────────────
   *
   * "Op my foon log die afrikaans steeds in in engels. Maar op die rekenaar
   * se login sien ek dit werk reg."
   *
   * Desktop working and phone not is the whole clue: the rule is right and
   * the thing it reads is missing. Every branch of it starts from
   * `localStorage.getItem(STORAGE_KEY)`, and there are browsers where that
   * throws or is silently discarded — Safari private browsing, an in-app
   * webview, or ITP clearing site data after a week of not visiting. All
   * three are ordinary on a phone and none of them happens on her laptop.
   *
   * In one of those, pressing Afrikaans on the sign-in screen works: the page
   * turns Afrikaans, and `setLang`'s write throws into a catch that says "then
   * it is applied for this page". Then she signs in, and the handler asks
   * storage what she chose. Storage says nothing. So rule 1 — a choice in this
   * browser wins — never fires, the account has nothing either (she was not
   * signed in when she chose, so it could not be written up), and `deviceWould`
   * reports what her phone's locale says, which is English.
   *
   * Every step is behaving as designed, and she is reading English.
   *
   * ── Why a ref, when the last ref was the bug ─────────────────────────
   *
   * The ref removed above held *what was painted*, updated by an effect, and
   * raced the sign-in listener that fires inside the first effect pass. This
   * one holds something different and has no such race: it is written
   * **synchronously inside `setLang`**, at the moment of the press, and it
   * only ever holds a deliberate choice. There is nothing to be stale — a
   * press has either happened before the listener reads it or it has not.
   *
   * It stands in for storage rather than replacing it. Storage is still
   * written and still read first; this answers only when storage could not.
   */
  const chose = useRef<Lang | null>(null);

  /** What this browser was told: storage, then the cookie, then this session. */
  const wasChosen = (): Lang | null => {
    try {
      const kept = asLang(window.localStorage.getItem(STORAGE_KEY));
      if (kept) return kept;
    } catch {
      // Blocked. The cookie below is the record that survives that.
    }
    const baked = inCookie();
    if (baked) return baked;
    return chose.current;
  };

  /**
   * The choice carried through a sign-in in the address bar.
   *
   * `cloud.signInWith` puts it on `redirectTo`, so it comes back on the return
   * leg of a Google, Apple or Facebook sign-in whatever happened to storage in
   * between — a home-screen app handing off to a browser does not share a
   * cookie jar with it, and that is the case none of the three device-side
   * copies can cover.
   *
   * Read once and taken straight out of the address, so a refresh or a shared
   * link does not pin somebody to a language they never chose. Same discipline
   * as `justArrived`.
   */
  /* Recorded rather than only used, so `/taal` can print it. Nothing here
     changes what the app does — it is the same four reads, kept. */
  const [sources, setSources] = useState<LangSources>(NOTHING_YET);

  const fromAddress = (): Lang | null => {
    try {
      const url = new URL(window.location.href);
      const said = asLang(url.searchParams.get(FROM_SIGNIN));
      if (!said) return null;
      url.searchParams.delete(FROM_SIGNIN);
      window.history.replaceState({}, '', `${url.pathname}${url.search}${url.hash}`);
      return said;
    } catch {
      return null;
    }
  };

  /* The document's own language, kept in step with the app's.
     `<html lang="en">` is written by the server, which cannot know — and an
     Afrikaans page that says it is English is read aloud by a screen reader
     in an English voice, word by word, and is filed by search engines as
     English. Neither is visible on the screen, which is why it stayed wrong. */
  useEffect(() => {
    document.documentElement.lang = lang;
  }, [lang]);

  // Read after mount: the server has no way to know, and guessing during render
  // would mismatch the HTML it sent.
  useEffect(() => {
    try {
      /* Storage first, then the cookie. On a browser that keeps neither this
         is null and the locale answers, which is the old behaviour; on one
         that keeps only the cookie — a phone after signing in — the choice is
         still a choice, and rule 1 applies instead of the account. */
      /* The address first, then storage, then the cookie.

         The address is only ever set by this app's own `redirectTo`, and only
         on the leg coming back from a sign-in — so when it is there it is the
         most recent thing anybody pressed, and it is the only one of the four
         that survives the round trip on a phone. It is written down here as
         well, so the next load does not depend on the address again. */
      const carried = fromAddress();
      if (carried) {
        chose.current = carried;
        bakeCookie(carried);
        noteWriter('signin');
        try {
          window.localStorage.setItem(STORAGE_KEY, carried);
        } catch {
          // The cookie and the ref still hold it.
        }
      }

      /* Each read kept apart, and a storage that *threw* kept apart from a
         storage that was simply empty. Those two are the same blank on screen
         and they mean opposite things — the first is a phone refusing to keep
         anything, the second is somebody who has not chosen yet. Telling them
         apart is the whole point of printing this. */
      let stored: Lang | 'blocked' | null = null;
      try {
        stored = asLang(window.localStorage.getItem(STORAGE_KEY));
      } catch {
        stored = 'blocked';
      }
      const baked = inCookie();
      const locale = navigator.language ?? '';
      const installed =
        window.matchMedia?.('(display-mode: standalone)').matches === true ||
        (window.navigator as { standalone?: boolean }).standalone === true;

      const arrived = onArrival(
        carried ?? (stored === 'blocked' ? null : stored) ?? baked,
        locale,
      );
      setSources({
        address: carried,
        storage: stored,
        cookie: baked,
        locale,
        account: 'unasked',
        won: carried
          ? 'address'
          : stored && stored !== 'blocked'
            ? 'storage'
            : baked
              ? 'cookie'
              : 'locale',
        installed,
        writer: whoWrote(),
      });
      setLangState(arrived.lang);
      /* A choice ends it here. A guess does not: the account below may still
         have something to say, and rule 3 is that a guess does not outrank
         somebody who told us once on another device. */
      if (arrived.fromChoice) return;
    } catch {
      // Storage blocked. English it is.
    }

    /* And then the account, if it has an answer this device does not.

       Somebody who chose Afrikaans on their phone and then opens a laptop has
       already told us once, and being asked again is the app forgetting. Only
       when nothing is stored here — a choice made in this browser is a choice
       about this browser and is never overruled — and only if they have not
       chosen in the moment it took to ask. */
    let stillUnasked = true;
    void (async () => {
      try {
        /* The press counts here too. Without it, a browser that cannot store
           asks the account on every load and lets it overrule a choice made a
           moment ago on this very page. */
        if (wasChosen()) return;
        const cloud = await import('./cloud');
        if (!cloud.configured()) return;
        // Asked of the server, not of the session in this browser — see
        // `accountLanguage`. The cached copy is the one thing that cannot
        // answer this, because a new device's session predates the choice.
        const said = await cloud.accountLanguage();
        if (!stillUnasked || !said) return;
        // Asked again after the wait: they may have pressed while it flew.
        if (wasChosen()) return;
        setLangState(said);
        document.documentElement.lang = said;
      } catch {
        // Whatever this device worked out on its own stands.
        setSources((was) => ({ ...was, account: 'failed' }));
      }
    })();
    return () => {
      stillUnasked = false;
    };
  }, []);

  /* ── Signing in, on a device that has not been told ────────────────────

     The effect above asks the account only at mount, and at mount nobody has
     signed in yet — so the answer is always "no session", and nothing ever
     asked again. What that cost: somebody who chooses Afrikaans on their
     phone and then signs in on a laptop gets English, with no path anywhere
     in the app that ever corrects it. It reads as the language reverting at
     the moment of signing in, because that is exactly when it happens.

     There is a second half. Choosing a language while signed out cannot be
     written to an account that does not exist yet, so `keepOnAccount` fails
     quietly — which is right, nobody did anything wrong — and the choice was
     never recorded at all. Signing in is the first moment it can be, so this
     is where it is done.

     The rule between the two, unchanged: a choice made in this browser is a
     choice about this browser and is never overruled. Storage wins when it
     has an answer, and the account is brought into step with it. The account
     answers only when this browser has nothing to say. */
  useEffect(() => {
    let live = true;
    let stop = () => undefined as void;
    void (async () => {
      try {
        const cloud = await import('./cloud');
        if (!live || !cloud.configured()) return;
        stop = cloud.onAccountChange((account) => {
          if (!account) return;
          void (async () => {
            /* Storage first, then the press. On a browser that cannot keep
               the choice, the press is the only record of it — and without
               this the rule falls through to the device's locale and undoes
               what she just asked for. */
            const stored: string | null = wasChosen();
            /* Asked only when this browser has nothing to say, because that is
               the only case the answer changes anything — and it is a network
               call. */
            const said = asLang(stored) ? null : await cloud.accountLanguage();
            if (!live) return;
            const next = onSignIn(stored, said, deviceWould(stored));
            if (next.keepOnAccount) {
              await keepOnAccount(next.keepOnAccount);
              return;
            }
            if (!next.store) return;
            /* Changed under somebody who was already reading, so say so.

               The rule above is right and stays: a person who chose Afrikaans
               on their phone should not have to choose again on a laptop. What
               was wrong is that the laptop had been showing English, they had
               been reading it, and signing in swapped it with no explanation —
               which reads as the app losing its place rather than remembering
               theirs.

               Only when it actually differs from what is on screen. A page
               that was already in the account's language changed nothing and
               has nothing to announce. */
            if (next.switched) setSwitched(next.switched);
            setLangState(next.lang);
            try {
              /* Stored, not only applied. Without this the next page load on
                 this device starts in English again and the account is asked
                 all over again — and on a slow connection that is a visible
                 flip from English to Afrikaans on every load. */
              window.localStorage.setItem(STORAGE_KEY, next.store);
              noteWriter('account');
            } catch {
              // Then it is applied for this page and asked again next time.
            }
            document.documentElement.lang = next.lang;
          })();
        });
      } catch {
        // No accounts configured. Whatever this device worked out stands.
      }
    })();
    return () => {
      live = false;
      stop();
    };
  }, []);

  /* Back to what was on screen, and written down this time.

     Pressing it is a choice, so it is stored like any other choice and the
     account is brought into step with it — which also means the notice never
     comes back on this device. Being told twice about the same thing is worse
     than not being told at all. */
  const undoSwitch = useCallback(() => {
    setSwitched((was) => {
      if (was) {
        // A press, like any other. Same reason as `setLang`.
        chose.current = was;
        bakeCookie(was);
        noteWriter('kept');
        setLangState(was);
        try {
          window.localStorage.setItem(STORAGE_KEY, was);
          document.documentElement.lang = was;
        } catch {
          // Applied for this page; asked again next time, and that is fine.
        }
        void keepOnAccount(was);
      }
      return null;
    });
  }, []);

  const setLang = useCallback((next: Lang) => {
    /* Any deliberate choice also puts the notice away: it is about a change
       nobody asked for, and this is somebody asking. */
    setSwitched(null);
    /* Written before anything that can fail, and synchronously, so a browser
       that refuses to store still knows what was pressed. See `chose`. */
    chose.current = next;
    /* Recorded as a press, beside the value. `/taal` prints it, and it is the
       row that would have answered her seventh report in one screenshot
       instead of another round of theories. */
    noteWriter('pressed');
    /* Before storage, because storage is the one that throws. A cookie
       written first is a choice that survives the reload signing in causes,
       whatever localStorage does about it. */
    bakeCookie(next);
    setLangState(next);
    try {
      window.localStorage.setItem(STORAGE_KEY, next);
      document.documentElement.lang = next;
    } catch {
      // The cookie above already holds it; this is the faster read.
    }
    void keepOnAccount(next);
  }, []);

  const t = useCallback(
    (key: string, fallback?: string) => STRINGS[key]?.[lang] ?? fallback ?? STRINGS[key]?.en ?? key,
    [lang],
  );

  const value = useMemo(
    () => ({ lang, setLang, t, switched, undoSwitch, sources }),
    [lang, setLang, t, switched, undoSwitch, sources],
  );
  return <Context.Provider value={value}>{children}</Context.Provider>;
}

export function useLang(): LangContext {
  return useContext(Context);
}
